-- Static workbook values extracted from QBE ASSESSMENT.xlsx, JOB SHEET.xlsx, and CMS - template.xlsb.
-- Generated from local workbook contents; safe to re-run via npm run db:migrate.

-- Staff names found in workbook dropdown/source lists.
ON CONFLICT (full_name) DO NOTHING;

-- Insurers / insurer-like entities found in workbook static lists.
ON CONFLICT (name) DO NOTHING;

-- Generic static dropdown/reference values. Existing friendly labels are preserved; source metadata is merged into extra.
ON CONFLICT (domain, code) DO UPDATE SET
  extra = COALESCE(lookup_values.extra, '{}'::jsonb) || EXCLUDED.extra,
  active = TRUE;

ON CONFLICT (domain, code) DO UPDATE SET
  extra = COALESCE(lookup_values.extra, '{}'::jsonb) || EXCLUDED.extra,
  active = TRUE;

ON CONFLICT (domain, code) DO UPDATE SET
  extra = COALESCE(lookup_values.extra, '{}'::jsonb) || EXCLUDED.extra,
  active = TRUE;

