  extra = COALESCE(lookup_values.extra, '{}'::jsonb) || EXCLUDED.extra,
  active = TRUE;

ON CONFLICT (domain, code) DO UPDATE SET
  extra = COALESCE(lookup_values.extra, '{}'::jsonb) || EXCLUDED.extra,
  active = TRUE;

ON CONFLICT (domain, code) DO UPDATE SET
  extra = COALESCE(lookup_values.extra, '{}'::jsonb) || EXCLUDED.extra,
  active = TRUE;

ON CONFLICT (domain, code) DO UPDATE SET
  extra = COALESCE(lookup_values.extra, '{}'::jsonb) || EXCLUDED.extra,
  active = TRUE;

ON CONFLICT (domain, code) DO UPDATE SET
  extra = COALESCE(lookup_values.extra, '{}'::jsonb) || EXCLUDED.extra,
  active = TRUE;

ON CONFLICT (domain, code) DO UPDATE SET
  extra = COALESCE(lookup_values.extra, '{}'::jsonb) || EXCLUDED.extra,
  active = TRUE;

ON CONFLICT (domain, code) DO UPDATE SET
  extra = COALESCE(lookup_values.extra, '{}'::jsonb) || EXCLUDED.extra,
  active = TRUE;

-- Rate card values from workbook calculator/reference sections.
ON CONFLICT (code) WHERE effective_to IS NULL DO UPDATE SET
  label = EXCLUDED.label,
  category = EXCLUDED.category,
  metal_type = EXCLUDED.metal_type,
  origin = EXCLUDED.origin,
  rate = EXCLUDED.rate,
  unit = EXCLUDED.unit;

