  FROM workbook_watch_rates w
  LEFT JOIN insurers i ON i.name = w.insurer_name
  WHERE w.insurer_name IS NULL OR i.id IS NOT NULL
)
SELECT insurer_id, brand, rate_type, rate_value FROM resolved
ON CONFLICT (brand, (COALESCE(insurer_id, -1))) WHERE effective_to IS NULL DO UPDATE SET
  rate_type = EXCLUDED.rate_type,
  rate_value = EXCLUDED.rate_value;
