  ('customer_message_template', 'post_pack', 'post pack', 1, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 2, "text": "TEXT ONLY : Hi Julie, your trackable return post pack will arrive within the next few days. The instructions for return are enclosed in the same envelope. We look forward to assisting you with your insurance claim. Please visit www.cameronco.com.au for more information or contact us on 03 9836 9922"}}'::jsonb),
  ('insurer_note_template', 'post_pack', 'post pack', 1, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 2, "text": "Insured is currently deciding on replacement options. Validation to follow as soon as a decision is made"}}'::jsonb),
  ('customer_message_template', 'template_row_3', 'Template row 3', 2, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 3, "text": "TEXT ONLY Hello Natasha, I have just been speaking with Steven in relation to your APIA claim. Could you please advise a suitable time to call you and discuss your loss. Our office number is (03) 9836 9922. We have left a message on your mobile and hope to connect later today.jacqui_7@hotmail.comMore information can be found at www.cameronco.com.au"}}'::jsonb),
  ('insurer_note_template', 'template_row_3', 'Template row 3', 2, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 3, "text": "We have contacted the customer via phone and text and are awaiting a response"}}'::jsonb),
  ('customer_message_template', 'post_pack_3', 'post pack', 3, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 4, "text": "TEXT ONLY Hi Marlene, Confirming we have received your ring today. We expect approx a 3 week turnaround to replace your diamond. We shall call to arrange delivery once your ring is repaired. Cheers Mark Cameronco.com.au 03 9836 9933"}}'::jsonb),
  ('insurer_note_template', 'post_pack_3', 'post pack', 3, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 4, "text": "We have sent a post pack to the customer to retrieve the item. Validation to be lodged as soon as we receive the ring"}}'::jsonb),
  ('customer_message_template', 'intro', 'INTRO', 4, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 5, "text": "TEXT ONLY: Good afternoon Kirsten, Cameron & Co Jewellers has received your insurance claim no: H0###### One of our Jewellery Consultants will contact you within 24 hours to discuss your claim. Kind regards, Mark from Cameron & Co (03) 9836 9922"}}'::jsonb),
  ('insurer_note_template', 'intro', 'INTRO', 4, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 5, "text": "Laura has an appointment for Monday 11/5 to discuss the repair, Cheers Mark"}}'::jsonb),
  ('customer_message_template', 'template_row_6', 'Template row 6', 5, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 6, "text": "TEXT ONLY: Good morning Paul, Cameron & Co has received your insurance claim from GIO Insurance. One of our Jewellery Consultants will contact you within 24 hours to discuss your claim. Kind regards Mark @ Cameron & Co (03) 9836 9922 www.cameronco.com.au 60"}}'::jsonb),
  ('insurer_note_template', 'template_row_6', 'Template row 6', 5, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 6, "text": "We are still trying to connect again with the customer. We will keep calling and texting. Cheers Mark"}}'::jsonb),
  ('customer_message_template', 'template_row_7', 'Template row 7', 6, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 7, "text": "Good afternoon Alisha, Cameron & Co has received your insurance claim from AAMI Insurance. One of our Jewellery Consultants will contact you within two business days to discuss your claim. Kind regards Mark @ Cameron & Co (03) 9836 9922 www.cameronco.com.au"}}'::jsonb),
  ('customer_message_template', 'left_a_message', 'LEFT A MESSAGE', 7, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 8, "text": "TEXT ONLY: Hello Rachel, AAMI have asked us to call you regarding your recent insurance claim. We have recently left a message on your mobile to discuss this further. If you have a moment, could you please call 03 9836 9922 and we can progress your claim. Many thanks Mark 60"}}'::jsonb),
  ('insurer_note_template', 'left_a_message', 'LEFT A MESSAGE', 6, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 8, "text": "Hi Team, can you please supply the policy limits. Thank you"}}'::jsonb),
  ('customer_message_template', 'missed_calls', 'MISSED CALLS', 8, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 9, "text": "TEXT ONLY: Hello Tim, ANZ Insurance has asked us to call you regarding your recent insurance claim. We have tried a few times to date without success. If you have a moment, could you please call 03 9836 9922 so that we can progress your claim. Many thanks Mark 60"}}'::jsonb),
  ('insurer_note_template', 'missed_calls', 'MISSED CALLS', 7, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 9, "text": "Hi team, as per assessment report, customer is requesting c/s. CM please contact customer re settlement. PLEASE NOTE, a) customer not willing to discuss or view replacement options b) customer supplied valuations but was unwilling to discuss further EOO to satisfy the PDS requirements, liability value is only if you are willing to accept the limited EOO otherwise you will need to adjust further. Thank you, Deb@Cameron&Co"}}'::jsonb),
  ('customer_message_template', 'appt', 'APPT', 9, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 10, "text": "TEXT ONLY: Thank you for your time today Bronwyn. Your appointment is scheduled for tomorrow at 2pm 19/7/22. Cameron & Co is situated at 73-75 Canterbury Road, Canterbury (Burke Road end of Canterbury Road). We are a commercial jeweller and have a locked door policy so please just ring the bell on arrival. Our contact number is 9836 9922. Cheers Mark @ Cameron & Co www.cameronco.com.au"}}'::jsonb),
  ('insurer_note_template', 'appt', 'APPT', 8, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 10, "text": "Hi, Address confirmed with the insured and we will be sending item by registered post today. Once collected we will lodge our invoice."}}'::jsonb),
  ('customer_message_template', 'directions', 'DIRECTIONS', 10, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 11, "text": "TEXT ONLY: Thank you for your time today . Cameron & Co is situated at 73-75 Canterbury Road, Canterbury (Burke Road end of Canterbury Road). Ph 03 9836 9922. We are a commercial jeweller and have a locked door policy so please just ring the bell on arrival. Parking is easy during the day until 4pm. You should find a spot directly out the front (no meters) or just around the corner in either Wentworth Ave or Gwenda Ave after 4pm. Cheers Mark @ Cameronco www.cameronco.com.au"}}'::jsonb),
  ('insurer_note_template', 'directions', 'DIRECTIONS', 9, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 11, "text": "Thank you... for our reporting to Suncorp, was the insured cash settled or alternative supplier? Thanks Mark"}}'::jsonb),
  ('customer_message_template', 'return_docs', 'RETURN DOCS', 11, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 12, "text": "TEXT ONLY Cameron & Co has been asked by AAMI to assist with your jewellery insurance claim. Please forward any photos or documentation you may have for your jewellery via email to claims@cameronco.com.au. If you prefer text, please reply to this message on 0490819488 so we may assist with your claim. Many thanks. More information can be found at www.cameronco.com.au or phone 03 9836 9922. Cheers Mark"}}'::jsonb),
  ('insurer_note_template', 'return_docs', 'RETURN DOCS', 10, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 12, "text": "Hi , email notification of a note received, but no note lodged. Please advise. Regards Cameron & Co"}}'::jsonb),
  ('customer_message_template', 'valuation', 'VALUATION', 12, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 13, "text": "TEXT ONLY: Please find attached your valuation from Cameron & Co for your recent insurance claim. Regards, Cameron & Co 03 9836 9922 www.cameronco.com.au"}}'::jsonb),
  ('insurer_note_template', 'valuation', 'VALUATION', 11, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 13, "text": "Customer has specifically requested a cash settlement"}}'::jsonb),
  ('customer_message_template', 'about_us', 'ABOUT US', 13, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 14, "text": "TEXT ONLY : Hello Graham, thank you for your time this morning regarding your jewellery insurance claim. For your reference, our office number is (03) 9836 9922. Cameron & Co works specifically to assist people with their insurance claims, providing current appraisals of lost items as well as replacement pieces. Cameron & Co has a proven and trusted reputation with your Insurer for industry knowledge, extensive range of product, design/manufacture and service levels. More information can be found at www.cameronco.com.au Regards Mark 59598"}}'::jsonb),
  ('insurer_note_template', 'about_us', 'ABOUT US', 12, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 14, "text": "Independent Valuation included $20.90 delivery if required"}}'::jsonb),
  ('customer_message_template', 'nsw_address_details', 'NSW ADDRESS DETAILS', 14, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 15, "text": "Hi Nadia, confirming your appt is for Thurs 2nd Dec @ 10.30am with Heather. The address is Suite 502, 321 Pitt St Sydney...5th floor, turn right out of lift (we are directly in front) and press the buzzer. Regards Deb, Cameron & Co Jewellery and Watches"}}'::jsonb),
  ('insurer_note_template', 'nsw_address_details', 'NSW ADDRESS DETAILS', 13, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 15, "text": "Hi, Assessment appointment scheduled for"}}'::jsonb),
  ('customer_message_template', 'contact_email', 'CONTACT EMAIL', 15, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 16, "text": "Hello Helen, We have been trying to contact you regarding your insurance claim with APIA for your lost diamond. Please call Mark on 03 9836 9922 at your convenience to progress the assessment ."}}'::jsonb),
  ('insurer_note_template', 'contact_email', 'CONTACT EMAIL', 14, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 16, "text": "Insure is still trying to find EOO to progress the validation. We will keep contacting"}}'::jsonb),
  ('customer_message_template', 'template_row_17', 'Template row 17', 16, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 17, "text": "Hello Casey, We have been asked by Shannons Insurance to contact you regarding the jewellery component of your insurance claim. Please call Mark on 03 9836 9922 at your convenience to progress the assessment ."}}'::jsonb),
  ('insurer_note_template', 'template_row_17', 'Template row 17', 15, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 17, "text": "Hi Team… email notification received, but no note this end on Claims Hub. Thanks Mark Cameron & Co"}}'::jsonb),
  ('customer_message_template', 'template_row_18', 'Template row 18', 17, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 18, "text": "TEXT ONLY : Hello Sheree, Cameron & Co has been asked by AAMI Insurance to contact you regarding the jewellery component of your insurance claim. Please call Mark on 03 9836 9922 at your convenience to progress the assessment .For more information, please visit www.cameronco.com.au 60"}}'::jsonb),
  ('insurer_note_template', 'template_row_18', 'Template row 18', 16, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 18, "text": "Delivery and independent valuation included"}}'::jsonb),
  ('customer_message_template', 'template_row_20', 'Template row 20', 18, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 20, "text": "TEXT ONLY: Thank you for your time today Graham. For your reference, our office number is (03) 9836 9922. Cameron & Co works specifically to assist people with their insurance claims, providing current appraisals of lost items as well as replacement pieces. Cameron & Co has a proven and trusted reputation with your Insurer for industry knowledge, extensive range of product, design/manufacture and service levels. Cameron & Co is situated at 73-75 Canterbury Road, Canterbury (Burke Road end of Canterbury Road). We are a commercial jeweller and have a locked door policy so please just ring the bell. Regards Mark @ Cameronco www.cameronco.com.au 60"}}'::jsonb),
  ('insurer_note_template', 'template_row_20', 'Template row 20', 17, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 20, "text": "1. SUPPLY INCLUDES INDEPENDENT VALUATION & DELIVERY IF REQUIRED 2. CUSTOMER MAY CHOOSE ALTERNATIVE ITEM/S TO SAME VALUE IF PREFERRED"}}'::jsonb),
  ('customer_message_template', 'one_call_message', 'one call message', 19, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 21, "text": "TEXT ONLY: Hello Kim, AAMI has asked us to call you regarding your recent insurance claim. We have tried today without success. If you have a moment, could you please call 03 9836 9922 and we can progress your claim. Many thanks Mark @ Cameron & Co www.cameronco.com.au 60"}}'::jsonb),
  ('insurer_note_template', 'one_call_message', 'one call message', 18, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 21, "text": "Hi Team, what is the policy limit per item if the customer has no EOO for that item? Thanks Mark"}}'::jsonb),
  ('customer_message_template', 'nsw_directions', 'NSW directions', 20, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 22, "text": "TEXT ONLY: Hi Lynette, your appointment is for this coming Monday 19/9/22 at 11am. Our Sydney office is on the 5th floor of 321 Pitt St Sydney unit 502. Sharp right out of the elevator and Cameron Co is clearly on the door. Please ring the buzzer. Cheers Heather www.cameronco.com.au 96140"}}'::jsonb),
  ('insurer_note_template', 'nsw_directions', 'NSW directions', 19, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 22, "text": "Could you pls forward the policy limits for the listed items for our report please. Thanks Mark"}}'::jsonb),
  ('customer_message_template', 'completed_item', 'completed item', 21, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 23, "text": "TEXT ONLY: Hi Amanda… we are just contacting you to say that your ring is has been completed for your AAMI insurance claim. Please call 03 9836 9922 to arrange a pick up time or delivery. Cheers Mark 60"}}'::jsonb),
  ('customer_message_template', 'email_eoo', 'email eoo', 22, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 24, "text": "Hello Elda, Cameron & Co has been asked by QBE to assist with your jewellery insurance claim. Please return any photos or documentation you may have via email to claims@cameronco.com.au or if you prefer text reply to 0449 171 134 so we may assist with your claim. Many thanks. Mark More information can be found at www.cameronco.com.au or phone 03 9836 9922"}}'::jsonb),
  ('customer_message_template', 'template_row_25', 'Template row 25', 23, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 25, "text": "TEXT ONLY: Hi Leone, re GIO claim, we look forward to meeting with you on Friday, 7th Oct @ 12 noon. We are located @ 73-75 Canterbury Rd, Canterbury. Please press buzzer at entrance. Kind regards, Deborah @ Cameron & Co Jewellery and Watches P 9836 9922 E"}}'::jsonb),
  ('customer_message_template', 'parel_received', 'Parel received', 24, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 27, "text": "Good afternoon Anne, This is a courtesy text to let you know I have received your single diamond earring safely in the post. I will be in touch with with four claw replacement options. Many thanks, Lucy @ Cameron & Co (02) 9699 2266 www.cameronco.com.au"}}'::jsonb),
  ('customer_message_template', 'template_row_30', 'Template row 30', 25, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 30, "text": "Good afternoon Vicky, Cameron & Co has received your insurance claim from AAMI Insurance. One of our Jewellery Consultants will contact you within two business days to discuss your claim. Kind regards Mark @ Cameron & Co (03) 9836 9922 www.cameronco.com.au"}}'::jsonb),
  ('customer_message_template', 'template_row_31', 'Template row 31', 26, '{"source": {"workbook": "CMS - template.xlsb", "sheet": "NOTES", "row": 31, "text": "TEXT ONLY: Hi Brunina, I hope you had a great weekend! Cameron & Co has been asked by AAMI to assist with your jewellery insurance claim. Please return any photos or documentation you may have to this number or via email to vicsales@cameronco.com.au, so we may assist with your claim. Many thanks, Paige More information can be found at www.cameronco.com.au or phone 03 9836 9922"}}'::jsonb)
